/**
 * Unit and regression tests for {@link RemoteServlet}.
 *
 * @author Dale Visser
 */
public class RemoveServletTest {

	private final RemoveServlet servlet = new RemoveServlet();

	@Test
	public void testSES1958regression()
			throws RepositoryException, QueryResultHandlerException, IOException, BadRequestException {
		WorkbenchRequest request = mock(WorkbenchRequest.class);
		when(request.isParameterPresent(CONTEXT)).thenReturn(true);
		IRI context = SimpleValueFactory.getInstance().createIRI("<http://foo.org/bar>");
		when(request.getResource(CONTEXT)).thenReturn(context);
		Repository repository = mock(Repository.class);
		servlet.setRepository(repository);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		when(repository.getConnection()).thenReturn(connection);
		servlet.doPost(request, mock(HttpServletResponse.class));
		verify(connection).clear(eq(context));
	}

	@Test
	public void countAnswersTheNumberOfExplicitStatementsThatMatch() throws Exception {
		List<JsonNode> records = count(store(), "subj", "<urn:test:s>", "pred", "<urn:test:p>");

		assertThat(rows(records)).singleElement()
				.satisfies(row -> assertThat(row.get(0).path("value").asText()).isEqualTo("2"));
	}

	@Test
	public void countLimitsItselfToTheChosenGraph() throws Exception {
		List<JsonNode> records = count(store(), "subj", "<urn:test:s>", "context", "<urn:test:g>");

		assertThat(rows(records)).singleElement()
				.satisfies(row -> assertThat(row.get(0).path("value").asText()).isEqualTo("1"));
	}

	@Test
	public void countWithAnInvalidTermAnswersBadRequestNamingTheField() throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();
		List<JsonNode> records = count(store(), response, "pred", "<not an iri");

		assertThat(response.getStatus()).isEqualTo(400);
		JsonNode error = records.getLast();
		assertThat(error.path("type").asText()).isEqualTo("error");
		assertThat(error.path("code").asText()).isEqualTo("pred");
		assertThat(error.path("message").asText()).contains("predicate");
	}

	@Test
	public void pageDataListsTheGraphsToChooseFrom() throws Exception {
		List<JsonNode> records = request(store(), new MockHttpServletResponse());

		assertThat(records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.findFirst()
				.orElseThrow()
				.path("values")
				.get(0)
				.asText()).isEqualTo("context");
		assertThat(rows(records)).singleElement()
				.satisfies(row -> assertThat(row.get(0).path("value").asText()).isEqualTo("urn:test:g"));
	}

	private static Repository store() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(vf.createIRI("urn:test:s"), vf.createIRI("urn:test:p"), vf.createLiteral("one"));
			connection.add(vf.createIRI("urn:test:s"), vf.createIRI("urn:test:p"), vf.createLiteral("two"),
					vf.createIRI("urn:test:g"));
			connection.add(vf.createIRI("urn:test:other"), vf.createIRI("urn:test:p"), vf.createLiteral("three"));
		}
		return repository;
	}

	private static List<JsonNode> count(Repository repository, String... parameters) throws Exception {
		return count(repository, new MockHttpServletResponse(), parameters);
	}

	private static List<JsonNode> count(Repository repository, MockHttpServletResponse response, String... parameters)
			throws Exception {
		String[] withCount = new String[parameters.length + 2];
		withCount[0] = "count";
		withCount[1] = "true";
		System.arraycopy(parameters, 0, withCount, 2, parameters.length);
		return request(repository, response, withCount);
	}

	private static List<JsonNode> request(Repository repository, MockHttpServletResponse response,
			String... parameters) throws Exception {
		RemoveServlet countingServlet = new RemoveServlet();
		countingServlet.setRepository(repository);
		countingServlet.setRepositoryManager(mock(RepositoryManager.class));
		countingServlet.init(TestServletConfig.withParams("remove", "cookie-max-age", "300"));
		try {
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/remove");
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
			for (int index = 0; index < parameters.length; index += 2) {
				request.addParameter(parameters[index], parameters[index + 1]);
			}
			countingServlet.service(request, response);
			ObjectMapper mapper = new ObjectMapper();
			return response.getContentAsString().lines().map(line -> {
				try {
					return mapper.readTree(line);
				} catch (Exception e) {
					throw new IllegalStateException(e);
				}
			}).toList();
		} finally {
			countingServlet.destroy();
			repository.shutDown();
		}
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.flatMap(record -> {
					List<JsonNode> values = new ArrayList<>();
					record.path("values").forEach(values::add);
					return values.stream();
				})
				.toList();
	}
}
